// ===== 01 車検・点検 お客さま台帳（01_車検点検台帳/test.py と同じ例） =====
const P = FX.c01.periods;
eq(K.PERIODS, P, '有効期間の表が Excel版と同じ');
const C01 = FX.c01.sample.map(([name, tel, car, plate, kind, first, exp, guide, memo]) => ({ name, tel, car, plate, kind, first, exp, guide, memo }));
FX.c01.scen.forEach(sc => {
  const today = D(sc.today), tag = `[台帳 ${sc.today} ${sc.d1}/${sc.d2} 月=${sc.month || '空'}]`;
  sc.rows.forEach((w, i) => {
    const x = K.custCalc(C01[i], today, sc.d1, sc.d2);
    eq([I(x.g1), I(x.g2), x.rem, x.st, x.years === '車検なし' ? null : x.years, x.next === null ? null : I(x.next)], [w.g1, w.g2, w.rem, w.st, w.years, w.next], tag + ' ' + C01[i].name);
  });
  const g = K.guideList(C01, today, sc.d1, sc.d2, sc.month);
  eq([I(g.ms), I(g.me)], [sc.ms, sc.me], tag + ' 対象月の初日・末日');
  eq(g.list.map(o => o.c.name), sc.list, tag + ' 今月の案内（満了日の近い順）');
});
// 手で確かめた値（test.py と同じ）
const by = n => C01.find(c => c.name === n), T0 = D('2026-10-22');
eq([I(K.custCalc(by('山田 太郎'), T0, 60, 30).g1), I(K.custCalc(by('山田 太郎'), T0, 60, 30).g2)], ['2026-10-11', '2026-11-10'], '山田：満了12/10の60日前は10/11・30日前は11/10');
eq(K.custCalc(by('山本 一美'), T0, 60, 30).st, '急ぎ', '山本：残り30日は急ぎ');
eq(K.custCalc(by('加藤 九郎'), T0, 60, 30).st, 'OK', '加藤：残り61日はOK');
eq(K.custCalc(by('鈴木 次郎'), T0, 60, 30).st, '案内時期', '鈴木：残り59日は案内時期');
